#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    int maximumLength(std::vector<int>& nums) {
        std::unordered_map<long long, int> cnt;
        for (int x : nums) cnt[x]++;
        int ans = 0;
        if (cnt.count(1)) {
            ans = cnt[1] - (cnt[1] % 2 == 0 ? 1 : 0);
            cnt.erase(1);
        }
        for (auto const& [k, v] : cnt) {
            int t = 0;
            long long cur = k;
            while (cnt.count(cur) && cnt[cur] > 1) {
                cur = cur * cur;
                t += 2;
            }
            t += (cnt.count(cur) && cnt[cur] > 0) ? 1 : -1;
            ans = std::max(ans, t);
        }
        return std::max(ans, 1);
    }
};

import java.util.HashMap;
import java.util.Map;

class Solution {
    public int maximumLength(int[] nums) {
        Map<Long, Integer> cnt = new HashMap<>();
        for (int x : nums) cnt.put((long)x, cnt.getOrDefault((long)x, 0) + 1);
        int ans = 0;
        if (cnt.containsKey(1L)) {
            int c1 = cnt.get(1L);
            ans = c1 - (c1 % 2 == 0 ? 1 : 0);
            cnt.remove(1L);
        }
        for (long k : cnt.keySet()) {
            int t = 0;
            long cur = k;
            while (cnt.getOrDefault(cur, 0) > 1) {
                cur = cur * cur;
                t += 2;
            }
            t += (cnt.getOrDefault(cur, 0) > 0) ? 1 : -1;
            ans = Math.max(ans, t);
        }
        return Math.max(ans, 1);
    }
}

